/bin/zsh -c "cat > /private/tmp/verify-shop.mjs <<'EOF'
import {spawn} from 'node:child_process';
import {gzipSync} from 'node:zlib';
import {createHash} from 'node:crypto';
import assert from 'node:assert/strict';
const server = spawn('bun', ['dist/server.mjs'], {stdio: ['ignore', 'pipe', 'inherit']});
try {
 const port = await new Promise((resolve, reject) => {server.stdout.once('data', data => resolve(Number(data.toString().trim()))); server.once('error', reject);});
 const base = "'`http://127.0.0.1:${port}`;
 const doc = xml => Buffer.concat([Buffer.from('"'SHOPPDF'), gzipSync(xml)]);
 const post = (id, bytes) => fetch("'`${base}/upload?id=${id}`, {method:'"'POST', body:bytes});
 let r = await post('good', doc('<title>Supplies</title>')); assert.equal(r.status, 200); assert.equal((await r.json()).title, 'Supplies');
 const bad = Buffer.from('invalid'); r = await post('bad', bad); assert.equal(r.status, 422); assert.deepEqual(await r.json(), {kind:'unreadable',kept:true});
 r = await fetch("'`${base}/attachment?id=bad`); assert.equal(await r.text(), createHash('"'sha256').update(bad).digest('hex'));
 r = await post('large', doc('<title>' + 'a'.repeat(1024*1024) + '</title>')); assert.equal(r.status, 422);
 const slow = doc('<title delay=\"1000\">slow</title>');
 const requests = Array.from({length:4}, (_, i) => post("'`slow${i}`, slow));
 r = await fetch(`${base}/health`); assert.equal(await r.text(), '"'alive');
 const responses = await Promise.all(requests); assert.deepEqual(responses.map(x=>x.status).sort(), [422,422,422,503]);
 assert.equal(responses.find(x=>x.status===503).headers.get('retry-after'), '1');
 console.log('Built service checks passed: prefill, retention, size, timeout, queue, and health.');
} finally {server.kill();}
EOF
bun /private/tmp/verify-shop.mjs"

